<script setup>
useHead({title:'Управление сайтами',meta:[{name:'robots',content:'noindex,nofollow'}]})
const loading=ref(true),authenticated=ref(false),password=ref(''),busy=ref(false),error=ref(''),toast=ref('')
const session=ref(null),sites=ref([]),search=ref(''),filter=ref('all'),selected=ref(null),section=ref('general'),baseline=ref(''),domain=ref(''),preview=ref(null),newDialog=ref(false),newTitle=ref(''),newSlug=ref(''),confirmAction=ref(null)
const sections=[{key:'general',number:'',title:'Настройки сайта'},{key:'identity',number:'1–2',title:'Иконка и название'},{key:'metrics',number:'3–4',title:'Рейтинг и установки'},{key:'screenshots',number:'5',title:'Скриншоты'},{key:'description',number:'6',title:'Описание'},{key:'ratings',number:'7',title:'Распределение оценок'},{key:'reviews',number:'8',title:'Отзывы'},{key:'domains',number:'',title:'Домен и публикация'}]
const dirty=computed(()=>selected.value&&JSON.stringify({title:selected.value.title,slug:selected.value.slug,content:selected.value.content})!==baseline.value)
const filtered=computed(()=>sites.value.filter(s=>(filter.value==='all'||s.status===filter.value)&&`${s.title} ${s.slug} ${s.domains.map(d=>d.hostname).join(' ')}`.toLowerCase().includes(search.value.toLowerCase())))
const publishedCount=computed(()=>sites.value.filter(s=>s.status==='published').length)
const currentSection=computed(()=>sections.find(s=>s.key===section.value))
function notify(message){toast.value=message;setTimeout(()=>{toast.value=''},4000)}
function fail(e){error.value=e?.data?.data?.message||e?.data?.statusMessage||e.message||String(e);if(e?.status===401||e?.statusCode===401)authenticated.value=false}
function setSelected(value){selected.value=JSON.parse(JSON.stringify(value));baseline.value=JSON.stringify({title:value.title,slug:value.slug,content:value.content})}
async function refresh(){sites.value=await $fetch('/api/admin/sites')}
async function init(){try{session.value=await $fetch('/api/admin/session');authenticated.value=true;await refresh()}catch(e){if(e?.status!==401&&e?.statusCode!==401)fail(e)}finally{loading.value=false}}
async function signIn(){busy.value=true;error.value='';try{await $fetch('/api/admin/login',{method:'POST',body:{password:password.value}});password.value='';await init()}catch(e){fail(e)}finally{busy.value=false}}
async function signOut(){if(dirty.value){confirmAction.value={type:'logout',title:'Выйти без сохранения?',text:'Изменения в открытом редакторе будут потеряны.'};return}await finishLogout()}
async function finishLogout(){await $fetch('/api/admin/logout',{method:'POST'});authenticated.value=false;selected.value=null}
function openSite(site){setSelected(site);section.value='general';error.value=''}
function back(){if(dirty.value){confirmAction.value={type:'back',title:'Закрыть без сохранения?',text:'Изменения в открытом редакторе будут потеряны.'};return}selected.value=null;error.value=''}
async function create(){busy.value=true;error.value='';try{const created=await $fetch('/api/admin/sites',{method:'POST',body:{title:newTitle.value,slug:newSlug.value,content:session.value.template}});newDialog.value=false;newTitle.value='';newSlug.value='';await refresh();openSite(created);notify('Сайт создан. Замените данные шаблона своими.')}catch(e){fail(e)}finally{busy.value=false}}
async function save(){const saved=await $fetch(`/api/admin/sites/${selected.value.id}`,{method:'PUT',body:{title:selected.value.title,slug:selected.value.slug,content:selected.value.content,version:selected.value.version}});setSelected(saved);await refresh();return saved}
async function saveClick(){busy.value=true;error.value='';try{await save();notify('Черновик сохранён')}catch(e){fail(e)}finally{busy.value=false}}
async function publish(){busy.value=true;error.value='';try{if(dirty.value)await save();const result=await $fetch(`/api/admin/sites/${selected.value.id}/publish`,{method:'POST',body:{version:selected.value.version}});setSelected(result);await refresh();notify('Сайт опубликован')}catch(e){fail(e)}finally{busy.value=false}}
async function duplicate(site){busy.value=true;error.value='';try{const result=await $fetch(`/api/admin/sites/${site.id}/duplicate`,{method:'POST'});await refresh();openSite(result);notify('Копия создана как черновик')}catch(e){fail(e)}finally{busy.value=false}}
async function confirm(){const action=confirmAction.value;confirmAction.value=null;busy.value=true;error.value='';try{if(action.type==='back')selected.value=null;else if(action.type==='logout')await finishLogout();else if(action.type==='archive'){await $fetch(`/api/admin/sites/${action.site.id}`,{method:'DELETE'});if(selected.value?.id===action.site.id)selected.value=null;await refresh();notify('Сайт убран в архив и снят с публикации')}else if(action.type==='unpublish'){if(dirty.value)await save();const result=await $fetch(`/api/admin/sites/${selected.value.id}/unpublish`,{method:'POST',body:{version:selected.value.version}});setSelected(result);await refresh();notify('Сайт снят с публикации')}}catch(e){fail(e)}finally{busy.value=false}}
function addReview(){selected.value.content.reviews.push({id:crypto.randomUUID(),name:'Новый автор',avatar:'/assets/avatar-1.png',rating:5,date:new Date().toLocaleDateString('ru-RU',{day:'numeric',month:'long',year:'numeric'}),text:'',helpfulCount:'0'})}
function move(items,index,delta){const other=index+delta;if(other<0||other>=items.length)return;[items[index],items[other]]=[items[other],items[index]]}
async function uploadScreens(event){const files=[...event.target.files];busy.value=true;error.value='';try{if(selected.value.content.screenshots.length+files.length>30)throw new Error('Максимум 30 скриншотов');for(const file of files){if(file.size>10*1024*1024)throw new Error(`${file.name}: размер больше 10 МБ`);const form=new FormData();form.append('file',file);const result=await $fetch('/api/admin/upload',{method:'POST',body:form});selected.value.content.screenshots.push({src:result.url,alt:file.name.replace(/\.[^.]+$/,'')})}}catch(e){fail(e)}finally{busy.value=false;event.target.value=''}}
async function domainAction(action,hostname){busy.value=true;error.value='';try{const result=await $fetch(`/api/admin/sites/${selected.value.id}/domains${action==='verify'?'/verify':''}`,{method:action==='remove'?'DELETE':'POST',body:{hostname}});if(action==='verify'){notify(result.verified?'DNS подтверждён. Домен готов к работе.':`DNS ещё не совпадает. Найдено: ${result.records.join(', ')||'нет записей'}`);const updated=await $fetch(`/api/admin/sites/${selected.value.id}`);selected.value.domains=updated.domains}else{selected.value.domains=result.domains;domain.value='';notify(action==='remove'?'Домен отключён':'Домен добавлен')}await refresh()}catch(e){fail(e)}finally{busy.value=false}}
async function copyLink(site){try{await navigator.clipboard.writeText(location.origin+`/s/${site.slug}`);notify('Ссылка скопирована')}catch{notify('Ссылка: '+location.origin+`/s/${site.slug}`)}}
function exportSite(){const blob=new Blob([JSON.stringify({title:selected.value.title,slug:selected.value.slug,content:selected.value.content},null,2)],{type:'application/json'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=`${selected.value.slug}.json`;a.click();URL.revokeObjectURL(a.href)}
function updatePreview(){preview.value?.contentWindow?.postMessage({type:'site-preview',content:JSON.parse(JSON.stringify(selected.value.content))},location.origin)}
let previewTimer
watch(()=>selected.value?.content,()=>{clearTimeout(previewTimer);previewTimer=setTimeout(()=>{if(selected.value)updatePreview()},250)},{deep:true})
function beforeUnload(event){if(dirty.value){event.preventDefault();event.returnValue=''}}
onMounted(()=>{init();window.addEventListener('beforeunload',beforeUnload)})
onBeforeUnmount(()=>{clearTimeout(previewTimer);window.removeEventListener('beforeunload',beforeUnload)})
</script>
<template>
<div class="admin-shell">
 <div v-if="loading" class="admin-loading">Загрузка панели…</div>
 <div v-else-if="!authenticated" class="login-layout">
  <section class="login-story"><div class="admin-brand"><span class="brand-mark">S</span> Site Studio</div><span class="eyebrow">ОДИН ШАБЛОН. ВСЕ ВАШИ САЙТЫ.</span><h1>От идеи<br>до нового сайта.</h1><p>Меняйте контент, добавляйте скриншоты и публикуйте новые страницы — в одном месте.</p><div class="login-steps"><span>01 <b>Создайте копию</b></span><span>02 <b>Заполните 8 блоков</b></span><span>03 <b>Подключите домен</b></span></div><small>Панель управления сайтами</small></section>
  <section class="login-side"><form class="login-form" @submit.prevent="signIn"><span class="lock-symbol">↗</span><h2>С возвращением</h2><p>Войдите, чтобы управлять своими сайтами.</p><label>Пароль администратора<input v-model="password" type="password" autocomplete="current-password" required placeholder="Введите пароль" /></label><p v-if="error" class="admin-error" role="alert">{{error}}</p><button class="primary wide" :disabled="busy">{{busy?'Входим…':'Войти в панель'}} <span>→</span></button><small>Доступ только для администратора</small></form></section>
 </div>
 <template v-else>
  <aside class="admin-sidebar"><button class="admin-brand" @click="back"><span class="brand-mark">S</span> Site Studio</button><span class="sidebar-caption">РАБОЧЕЕ ПРОСТРАНСТВО</span><button class="sidebar-item active" @click="back"><AppIcon name="apps"/>Мои сайты <span>{{sites.length}}</span></button><div class="sidebar-note"><span class="status-dot"></span> Ваш шаблон готов<p>Создавайте сайты без изменения кода.</p></div><div class="sidebar-bottom"><div class="admin-avatar">A</div><div><strong>Администратор</strong><small>Полный доступ</small></div><button title="Выйти" aria-label="Выйти" @click="signOut">↪</button></div></aside>
  <div class="admin-workspace">
   <header class="admin-topbar"><div><button v-if="selected" class="breadcrumb" @click="back">Мои сайты</button><span v-else>Рабочее пространство</span><span v-if="selected" class="breadcrumb-separator">/</span><strong>{{selected?selected.title:'Мои сайты'}}</strong></div><button class="mobile-logout" @click="signOut">Выйти</button><span class="topbar-note">{{selected ? (dirty?'Есть несохранённые изменения':'Все изменения сохранены') : 'Шаблон Google Play'}}</span></header>
   <div v-if="error" class="admin-error global-error" role="alert">{{error}}<button aria-label="Закрыть сообщение" @click="error=''">×</button></div>
   <main v-if="!selected" class="dashboard">
    <div class="page-heading"><div><span class="eyebrow">ВАШИ ПРОЕКТЫ</span><h1>Мои сайты <span>{{sites.length}}</span></h1><p>Создавайте, редактируйте и публикуйте страницы приложений.</p></div><button class="primary" @click="newDialog=true">＋ Создать сайт</button></div>
    <div class="stats-row"><div><span>Всего сайтов</span><strong>{{sites.length}}</strong><small>В вашем пространстве</small></div><div><span><i class="status-dot"></i> Опубликовано</span><strong>{{publishedCount}}</strong><small>Доступны по ссылке</small></div><div><span><i class="status-dot amber"></i> Черновики</span><strong>{{sites.length-publishedCount}}</strong><small>Готовятся к запуску</small></div></div>
    <div class="list-toolbar"><div class="filter-tabs"><button :class="{active:filter==='all'}" @click="filter='all'">Все сайты</button><button :class="{active:filter==='published'}" @click="filter='published'">Опубликованные</button><button :class="{active:filter==='draft'}" @click="filter='draft'">Черновики</button></div><label class="search-box"><AppIcon name="search"/><input v-model="search" placeholder="Найти сайт…" aria-label="Поиск сайтов"/></label></div>
    <div class="site-grid"><article v-for="site in filtered" :key="site.id" class="site-card"><div class="site-card-cover"><div class="mini-page"><div class="mini-top"><span>▷</span> Google Play <i>•••</i></div><div class="mini-app"><img :src="site.content.icon" alt=""/><div><strong>{{site.content.name}}</strong><small>{{site.content.developer}}</small><span>{{site.content.rating}} ★ · {{site.content.downloads}}</span></div></div><div class="mini-install">Установить</div><div class="mini-shots"><img v-for="shot in site.content.screenshots.slice(0,5)" :key="shot.src" :src="shot.src" alt=""/></div></div><span class="status-badge" :class="site.status">{{site.status==='published'?'Опубликован':'Черновик'}}</span></div><div class="site-card-body"><h2>{{site.title}}</h2><p>{{site.domains[0]?.hostname || `/s/${site.slug}`}}</p><div class="site-card-meta"><span>{{site.hasChanges?'Есть неопубликованные правки':'Обновлён '+new Date(site.updatedAt).toLocaleDateString('ru-RU')}}</span><button class="icon-btn" title="Дублировать сайт" aria-label="Дублировать сайт" :disabled="busy" @click="duplicate(site)">⧉</button></div><div class="site-card-actions"><button class="secondary" @click="openSite(site)">Редактировать <span>→</span></button><a v-if="site.status==='published'" :href="`/s/${site.slug}`" target="_blank" rel="noopener" class="icon-btn" title="Открыть сайт">↗</a><button class="icon-btn danger" title="Убрать в архив" aria-label="Убрать в архив" @click="confirmAction={type:'archive',site,title:'Убрать сайт в архив?',text:'Сайт станет недоступен по ссылке и доменам. Данные останутся в резервном архиве базы.'}">×</button></div></div></article><button v-if="!search&&filter==='all'" class="new-site-card" @click="newDialog=true"><span>＋</span><strong>Новый сайт</strong><p>Начните с готового шаблона<br>или создайте копию существующего</p></button></div>
    <div v-if="!filtered.length&&(search||filter!=='all')" class="empty-results">Сайты не найдены. Попробуйте другой запрос или фильтр.</div>
   </main>
   <main v-else class="editor">
    <div class="editor-heading"><div><span class="eyebrow">РЕДАКТОР САЙТА</span><h1>{{selected.title}} <span class="status-badge" :class="selected.status">{{selected.status==='published'?'Опубликован':'Черновик'}}</span></h1></div><div class="editor-actions"><a class="secondary" :href="`/preview/${selected.id}`" target="_blank" rel="noopener" title="Сначала сохраните изменения">Предпросмотр ↗</a><button class="secondary" :disabled="busy" @click="saveClick">Сохранить</button><button class="primary" :disabled="busy" @click="publish">{{busy?'Подождите…':'Опубликовать'}} <span>↗</span></button></div></div>
    <div class="editor-layout"><nav class="section-nav" aria-label="Разделы редактора"><button v-for="item in sections" :key="item.key" :class="{active:section===item.key}" @click="section=item.key"><span>{{item.number||'•'}}</span>{{item.title}}</button><div class="nav-help">Правки сохраняются в черновик. Посетители увидят их после публикации.</div></nav>
     <section class="editor-panel"><div class="panel-heading"><span class="eyebrow">{{currentSection.number?'БЛОК '+currentSection.number:'УПРАВЛЕНИЕ'}}</span><h2>{{currentSection.title}}</h2></div>
      <div v-if="section==='general'" class="field-stack"><label>Название проекта<input v-model="selected.title" maxlength="100" placeholder="Например, Facebook — Украина"/><small>Видно только в админке</small></label><label>Адрес страницы<div class="input-prefix"><span>/s/</span><input v-model="selected.slug" maxlength="60" pattern="[a-z0-9-]+"/></div><small>Латинские буквы, цифры и дефис. При изменении старая ссылка перестанет работать.</small></label><label>Ссылка на приложение в Google Play<input v-model="selected.content.playStoreUrl" type="url"/><small>Все кнопки на странице ведут по этой ссылке.</small></label><div class="info-box">У каждого сайта свои тексты, изображения, отзывы и домены. Изменения здесь не затрагивают другие копии.</div><button class="secondary" @click="exportSite">↓ Выгрузить данные сайта</button></div>
      <div v-if="section==='identity'" class="field-stack"><AdminMedia v-model="selected.content.icon" label="Иконка приложения" @error="error=$event"/><label>Название приложения<input v-model="selected.content.name" maxlength="100"/></label><label>Разработчик<input v-model="selected.content.developer"/></label><label>Примечание<input v-model="selected.content.notice" placeholder="Есть реклама · Покупки в приложении"/></label></div>
      <div v-if="section==='metrics'" class="field-stack"><div class="two-fields"><label>Рейтинг<input v-model="selected.content.rating" inputmode="decimal" placeholder="4,7"/><small>Число от 0 до 5</small></label><label>Количество отзывов<input v-model="selected.content.reviewCount" placeholder="181 млн"/></label></div><label>Количество скачиваний<input v-model="selected.content.downloads" placeholder="10 млрд+"/></label><label>Возрастное ограничение<input v-model="selected.content.age" placeholder="12+"/></label><div class="info-box">Рейтинг и количество отзывов также обновятся в нижнем блоке оценок.</div></div>
      <div v-if="section==='screenshots'" class="field-stack"><p class="section-description">Изображения появятся в карусели в этом порядке. Можно добавить до 30 скриншотов.</p><label class="upload-zone"><span>＋</span><strong>{{busy?'Загружаем…':'Добавить скриншоты'}}</strong><small>Выберите один или несколько файлов · до 10 МБ каждый</small><input type="file" accept="image/png,image/jpeg,image/webp" multiple :disabled="busy" @change="uploadScreens"/></label><div class="screenshot-grid"><div v-for="(shot,index) in selected.content.screenshots" :key="shot.src+index" class="screenshot-item"><img :src="shot.src" :alt="shot.alt"/><input v-model="shot.alt" :aria-label="`Описание скриншота ${index+1}`" placeholder="Описание"/><div><button :disabled="index===0" aria-label="Переместить влево" @click="move(selected.content.screenshots,index,-1)">←</button><span>{{index+1}}</span><button :disabled="index===selected.content.screenshots.length-1" aria-label="Переместить вправо" @click="move(selected.content.screenshots,index,1)">→</button><button class="danger" aria-label="Удалить скриншот" @click="selected.content.screenshots.splice(index,1)">×</button></div></div></div><p v-if="!selected.content.screenshots.length" class="section-description">Скриншотов пока нет. На странице галерея будет скрыта.</p></div>
      <div v-if="section==='description'" class="field-stack"><label>Описание приложения<textarea v-model="selected.content.description" rows="10" maxlength="20000"/></label><label>Последнее обновление<input v-model="selected.content.updatedAt" placeholder="4 нояб. 2026 г."/></label><label>Категория<input v-model="selected.content.category"/></label><label>Позиция в категории<input v-model="selected.content.ranking"/></label></div>
      <div v-if="section==='ratings'" class="field-stack"><p class="section-description">Укажите длину каждой полосы в процентах — от 0 до 100.</p><div v-for="(_,index) in selected.content.ratingDistribution" :key="index" class="distribution-field"><span>{{5-index}} ★</span><input v-model.number="selected.content.ratingDistribution[index]" type="range" min="0" max="100" :aria-label="`${5-index} звёзд: шкала`"/><input v-model.number="selected.content.ratingDistribution[index]" type="number" min="0" max="100" :aria-label="`${5-index} звёзд: процент`"/><span>%</span></div><div class="info-box">Общий рейтинг {{selected.content.rating}} и число отзывов {{selected.content.reviewCount}} берутся из раздела «Рейтинг и установки».</div></div>
      <div v-if="section==='reviews'" class="field-stack"><div class="inline-heading"><p class="section-description">Отзывов: {{selected.content.reviews.length}}</p><button class="secondary" :disabled="selected.content.reviews.length>=100" @click="addReview">＋ Добавить отзыв</button></div><details v-for="(review,index) in selected.content.reviews" :key="review.id" class="review-editor" :open="index===0"><summary><img :src="review.avatar" alt=""/><span>{{review.name}}<small>{{review.rating}} ★ · {{review.date}}</small></span><span>⌄</span></summary><div class="field-stack"><AdminMedia v-model="review.avatar" label="Фото автора" compact @error="error=$event"/><label>Имя автора<input v-model="review.name"/></label><div class="two-fields"><label>Оценка<select v-model.number="review.rating"><option v-for="n in 6" :key="n" :value="n-1">{{n-1}} ★</option></select></label><label>Дата<input v-model="review.date"/></label></div><label>Текст отзыва<textarea v-model="review.text" rows="6"/></label><label>Сколько людей отметили полезным<input v-model="review.helpfulCount"/></label><div class="review-buttons"><button class="secondary" :disabled="index===0" @click="move(selected.content.reviews,index,-1)">↑ Выше</button><button class="secondary" :disabled="index===selected.content.reviews.length-1" @click="move(selected.content.reviews,index,1)">↓ Ниже</button><button class="text-danger" @click="selected.content.reviews.splice(index,1)">Удалить отзыв</button></div></div></details><p v-if="!selected.content.reviews.length" class="section-description">Отзывов пока нет. Добавьте первый отзыв.</p></div>
      <div v-if="section==='domains'" class="field-stack"><div class="publication-box"><span class="status-badge" :class="selected.status">{{selected.status==='published'?'Сайт опубликован':'Сайт пока не опубликован'}}</span><p>После публикации сайт можно открыть по ссылке, даже если домен ещё не подключён.</p><div class="publication-links"><a v-if="selected.status==='published'" :href="`/s/${selected.slug}`" target="_blank" rel="noopener">Открыть сайт ↗</a><button v-if="selected.status==='published'" @click="copyLink(selected)">Скопировать ссылку</button></div><button v-if="selected.status==='published'" class="text-danger" @click="confirmAction={type:'unpublish',title:'Снять сайт с публикации?',text:'Сайт перестанет открываться по ссылке и подключённым доменам. Черновик сохранится.'}">Снять с публикации</button></div><h3>Свой домен</h3><p class="section-description">Добавьте домен без https://. Для www добавьте отдельный адрес.</p><form class="domain-form" @submit.prevent="domainAction('add',domain)"><input v-model="domain" placeholder="example.com" aria-label="Новый домен" required/><button class="secondary" :disabled="busy">Добавить</button></form><div v-if="!session.serverIp" class="info-box">Сейчас система работает локально. Домены можно сохранить заранее. Для подключения понадобится VPS и его IP-адрес.</div><div v-else class="dns-guide"><strong>Настройка у регистратора</strong><p>Создайте A-запись для домена со значением <code>{{session.serverIp}}</code>. Удалите конфликтующие A/AAAA-записи, отключите DNS-прокси и нажмите «Проверить DNS».</p><small>После проверки DNS и публикации HTTPS подключится автоматически на настроенном сервере.</small></div><div v-for="item in selected.domains" :key="item.hostname" class="domain-row"><div><strong>{{item.hostname}}</strong><small :class="{verified:item.verified}">{{item.verified?'DNS подтверждён':'Ожидает настройки DNS'}}</small></div><button class="secondary" :disabled="busy||!session.serverIp" @click="domainAction('verify',item.hostname)">Проверить DNS</button><button class="icon-btn danger" aria-label="Отключить домен" @click="domainAction('remove',item.hostname)">×</button></div></div>
     </section>
     <aside class="preview-panel"><div><span class="status-dot"></span> Предпросмотр <a :href="`/preview/${selected.id}`" target="_blank" rel="noopener" title="Открыть сохранённый черновик">↗</a></div><div class="preview-phone"><iframe ref="preview" :key="selected.id" :src="`/preview/${selected.id}`" title="Предпросмотр страницы приложения" @load="updatePreview"/></div><small>Изменения видны только вам</small></aside>
    </div>
   </main>
  </div>
 </template>
 <div v-if="toast" class="toast" role="status"><span>✓</span>{{toast}}</div>
 <div v-if="newDialog" class="modal-overlay" @click.self="newDialog=false"><form class="admin-modal" @submit.prevent="create"><button type="button" class="modal-close" aria-label="Закрыть" @click="newDialog=false">×</button><span class="eyebrow">НОВЫЙ ПРОЕКТ</span><h2>Создать сайт</h2><p>Начните с шаблона Google Play и замените данные своими.</p><div class="field-stack"><label>Название проекта<input v-model="newTitle" required maxlength="100" placeholder="Например, Facebook — Украина" autofocus/></label><label>Адрес страницы<div class="input-prefix"><span>/s/</span><input v-model="newSlug" required pattern="[a-z0-9](?:[a-z0-9-]{0,58}[a-z0-9])?" placeholder="facebook-ua"/></div><small>Латинские буквы, цифры и дефис</small></label><p v-if="error" class="admin-error">{{error}}</p><button class="primary wide" :disabled="busy">{{busy?'Создаём…':'Создать черновик'}} →</button></div></form></div>
 <div v-if="confirmAction" class="modal-overlay"><section class="admin-modal"><h2>{{confirmAction.title}}</h2><p>{{confirmAction.text}}</p><div class="modal-actions"><button class="secondary" @click="confirmAction=null">Отмена</button><button class="primary" @click="confirm">Продолжить</button></div></section></div>
</div>
</template>
